// 需要安裝 Scriptable App: https://scriptable.app

const SUPA_URL = "https://jacclflkmhzsmkkjcrlp.supabase.co"
const ANON_KEY = "sb_publishable_nQ97A-osICZV_QeUiS8AOw_aWZAWJCK"

async function signIn(email, password) {
  const req = new Request(SUPA_URL + "/auth/v1/token?grant_type=password")
  req.method = "POST"
  req.headers = { "apikey": ANON_KEY, "Content-Type": "application/json" }
  req.body = JSON.stringify({ email, password })
  return req.loadJSON()
}

let email = Keychain.contains("voya_email") ? Keychain.get("voya_email") : ""
let password = Keychain.contains("voya_pass") ? Keychain.get("voya_pass") : ""

if (!email || !password) {
  const a = new Alert()
  a.title = "✈️ Voya 登入"
  a.message = "輸入你的 Voya 帳號，帳密將安全儲存於 Keychain"
  a.addTextField("Email", email)
  a.addSecureTextField("密碼")
  a.addAction("登入")
  a.addCancelAction("取消")
  const idx = await a.present()
  if (idx === -1) { Script.complete(); return }
  email = a.textFieldValue(0)
  password = a.textFieldValue(1)
}

const auth = await signIn(email, password)
if (!auth.access_token) {
  Keychain.remove("voya_email")
  Keychain.remove("voya_pass")
  const w = new ListWidget()
  w.backgroundColor = new Color("#1f2937")
  const t = w.addText("⚠️ 登入失敗，請重新執行")
  t.textColor = new Color("#f87171")
  t.font = Font.systemFont(12)
  Script.setWidget(w); w.presentSmall(); Script.complete(); return
}

Keychain.set("voya_email", email)
Keychain.set("voya_pass", password)

const today = new Date().toISOString().slice(0, 10)
const tripReq = new Request(
  SUPA_URL + "/rest/v1/trips?end_date=gte." + today + "&order=start_date.asc&limit=1&select=*"
)
tripReq.headers = {
  "apikey": ANON_KEY,
  "Authorization": "Bearer " + auth.access_token
}
const trips = await tripReq.loadJSON()

const w = new ListWidget()
const grad = new LinearGradient()
grad.colors = [new Color("#74b9e8"), new Color("#a8d8f0"), new Color("#deeef8")]
grad.locations = [0, 0.5, 1]
grad.startPoint = new Point(0, 0)
grad.endPoint = new Point(1, 1)
w.backgroundGradient = grad
w.setPadding(14, 16, 10, 16)

if (!trips || trips.length === 0) {
  w.addSpacer()
  const ic = w.addText("✈️")
  ic.font = Font.systemFont(28); ic.centerAlignText()
  w.addSpacer(6)
  const msg = w.addText("還沒有即將出發的行程")
  msg.font = Font.mediumSystemFont(11)
  msg.textColor = new Color("#3b5778")
  msg.centerAlignText()
  w.addSpacer()
} else {
  const trip = trips[0]
  const startDate = trip.start_date
  const now = new Date(); now.setHours(0,0,0,0)
  const sd = new Date(startDate); sd.setHours(0,0,0,0)
  const days = Math.round((sd - now) / 86400000)
  const emoji = trip.cover_emoji || "✈️"

  const titleRow = w.addStack()
  titleRow.layoutHorizontally()
  const et = titleRow.addText(emoji + " ")
  et.font = Font.systemFont(12); et.textColor = new Color("#1a2e4a")
  const tt = titleRow.addText(trip.title)
  tt.font = Font.boldSystemFont(12); tt.textColor = new Color("#1a2e4a"); tt.lineLimit = 1

  w.addSpacer(4)

  const dRow = w.addStack()
  dRow.layoutHorizontally(); dRow.bottomAlignContent(); dRow.addSpacer()
  if (days < 0) {
    const t = dRow.addText("旅途中 🌍")
    t.font = Font.boldSystemFont(18); t.textColor = new Color("#1a2e4a")
  } else if (days === 0) {
    const t = dRow.addText("今天出發！")
    t.font = Font.boldSystemFont(20); t.textColor = new Color("#dc2626")
  } else if (days === 1) {
    const t = dRow.addText("明天 ✈️")
    t.font = Font.boldSystemFont(24); t.textColor = new Color("#1a2e4a")
  } else {
    const n = dRow.addText(String(days))
    n.font = Font.boldSystemFont(44); n.textColor = new Color("#1a2e4a")
    const u = dRow.addText(" 天")
    u.font = Font.boldSystemFont(14); u.textColor = new Color("#3b5778")
  }
  dRow.addSpacer()

  w.addSpacer(4)
  const dt = w.addText(startDate + " 出發")
  dt.font = Font.systemFont(10); dt.textColor = new Color("#3b5778"); dt.centerAlignText()
}

w.addSpacer()
const brand = w.addText("Voya ✈️")
brand.font = Font.lightSystemFont(9)
brand.textColor = new Color("#3b577866")
brand.rightAlignText()

Script.setWidget(w)
w.presentSmall()
Script.complete()
